    pub(crate) const SEMANTIC_STYLE_DIRECTION: TextDirection = TextDirection::Auto;
    pub(crate) const SEMANTIC_STYLE_EMPHASIS: Emphasis = Emphasis::Normal;
    pub(crate) const SEMANTIC_STYLE_ROLE: StyleRole = StyleRole::None;
